pub fn makeBuiltinLookupTree(mut name: ArcStr, mut components: Arc<metamodelica::List<ArcStr>>, mut classes: Arc<metamodelica::List<ArcStr>>) -> Result<()> {
    let mut ltree: Arc<LookupTree::Tree> = LookupTree::new();
    let mut i: i32 = 0;
    i = 1;
    for mut comp in &*components.clone() {
        let mut comp = comp.clone();
        ltree = LookupTree::add(ltree.clone(), (comp.clone()).clone(), Arc::new(LookupTree::Entry::Entry::COMPONENT { index: i.clone() }), LookupTree::addConflictDefault)?;
        i = i.clone() + 1;
    }
    for mut cls in &*classes.clone() {
        let mut cls = cls.clone();
        ltree = LookupTree::add(ltree.clone(), (cls.clone()).clone(), Arc::new(LookupTree::Entry::Entry::COMPONENT { index: i.clone() }), LookupTree::addConflictDefault)?;
        i = i.clone() + 1;
    }
    println!("{}", ({ let mut __mm_s = String::new(); __mm_s.push_str(&*literal!("Lookup tree for ")); __mm_s.push_str(&*name.clone()); __mm_s.push_str(&*literal!(":\n")); ArcStr::from(__mm_s) }).clone());
    println!("{}", (anyString(ltree.clone())).clone());
    println!("{}", (literal!("\n")).clone());
    Ok(())
}

